const feedPostIDs = `-- name: FeedPostIDs :many
SELECT p.id FROM social.post p LEFT JOIN social.community c ON c.id=p.community_id
LEFT JOIN social.post_stats s ON s.post_id=p.id
WHERE p.state='PUBLISHED' AND (c.id IS NULL OR c.visibility IN ('PUBLIC','RESTRICTED'))
  AND (c.id IS NULL OR c.state='ACTIVE') AND (p.author_id IS NULL OR EXISTS(SELECT 1 FROM social.profile author WHERE author.id=p.author_id AND author.state='ACTIVE'))
  AND ($1::uuid='00000000-0000-0000-0000-000000000000'::uuid OR p.community_id=$1)
  AND (NOT $2::boolean OR EXISTS(SELECT 1 FROM social.bookmark bm WHERE bm.profile_id=$3 AND bm.post_id=p.id))
  AND ($2::boolean OR NOT EXISTS(SELECT FROM social.mute m WHERE m.profile_id=$3 AND (m.muted_profile_id=p.author_id OR m.muted_community_id=p.community_id) AND (m.expires_at IS NULL OR m.expires_at>statement_timestamp())))
  AND (NOT $4::boolean OR EXISTS(SELECT 1 FROM social.community_follow cf WHERE cf.profile_id=$3 AND cf.community_id=p.community_id)
    OR EXISTS(SELECT 1 FROM social.profile_follow pf WHERE pf.follower_id=$3 AND pf.followed_id=p.author_id))
  AND ($5::text='' OR strpos(lower(COALESCE((SELECT body||' '||COALESCE(title,'') FROM social.post_revision WHERE post_id=p.id AND revision=p.published_revision),'')),lower($5))>0)
  AND NOT EXISTS(SELECT 1 FROM social.profile_block b WHERE (b.blocker_id=$3 AND b.blocked_id=p.author_id) OR (b.blocked_id=$3 AND b.blocker_id=p.author_id))
ORDER BY CASE WHEN $6::boolean THEN COALESCE(s.up_count-s.down_count,0) ELSE 0 END DESC,p.published_at DESC,p.id DESC LIMIT 200
`

type FeedPostIDsParams struct {
	CommunityID   uuid.UUID `json:"community_id"`
	SavedOnly     bool      `json:"saved_only"`
	ViewerID      uuid.UUID `json:"viewer_id"`
	FollowingOnly bool      `json:"following_only"`
	SearchText    string    `json:"search_text"`
	SortTop       bool      `json:"sort_top"`
}

func (q *Queries) FeedPostIDs(ctx context.Context, arg FeedPostIDsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, feedPostIDs,
		arg.CommunityID,
		arg.SavedOnly,
		arg.ViewerID,
		arg.FollowingOnly,
		arg.SearchText,
		arg.SortTop,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

